rm -rf dist && mkdir -p /tmp/dash-check && cat > /tmp/dash-check/check.cjs <<'EOF'
const Module = require('module');
Module._extensions['.css'] = () => {};
const { DashKit } = require('/home/sandbox/workspace/node_modules/@gravity-ui/dashkit');
const config = {salt: 's', counter: 0, items: [], layout: [], aliases: {}, connections: []};
let c = config;
const placements = [
  ['kpi', {metric:'revenue'}, 0,0,9,4],['kpi', {metric:'orders'}, 9,0,9,4],['kpi', {metric:'conversion'},18,0,9,4],['kpi', {metric:'users'},27,0,9,4],
  ['revenue-chart', {}, 0,4,22,10],['channels-chart', {}, 22,4,14,10],['activity', {}, 0,14,18,8]];
for (const [type,data,x,y,w,h] of placements) c = DashKit.setItem({item:{type,data,namespace:'default',layout:{x,y,w,h}},config:c});
console.log('items', c.items.length, 'layout', c.layout.length, 'counter', c.counter);
console.log(JSON.stringify(c.layout));
const added = DashKit.setItem({item:{type:'kpi',data:{metric:'users'},namespace:'default'},config:c});
console.log('after add: items', added.items.length, 'new layout', JSON.stringify(added.layout.at(-1)));
EOF
node /tmp/dash-check/check.cjs 2>&1 | tail -20

